using System.Security.Cryptography;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.TestHost;
using Microsoft.Extensions.DependencyInjection;

namespace Apogeu.DemoCasino.Tests.Support;

/// <summary>
/// The real DemoCasino in memory (WebApplicationFactory), configured only with values generated by the test (ADR-0014: no
/// real credential anywhere): the Apogeu base URL and the demo operator key of the contract (SPEC-0043 §6,
/// <c>Apogeu:BaseUrl</c>, <c>Apogeu:OperatorKeyId</c>, <c>Apogeu:OperatorSecret</c>).
/// </summary>
internal sealed class DemoCasinoHost : IAsyncDisposable
{
    /// <summary>Address of the Apogeu API seen by the casino; nothing listens there (the tests never reach it).</summary>
    public static readonly Uri ApogeuBaseUrl = new("https://api.apogeu.test/");

    /// <summary>HTTPS, so a cookie marked Secure is still kept and sent by the test client.</summary>
    public static readonly Uri CasinoBaseAddress = new("https://casino.apogeu.test");

    private readonly WebApplicationFactory<Program> _factory;

    private DemoCasinoHost(WebApplicationFactory<Program> factory, string operatorKeyId, string operatorSecret)
    {
        _factory = factory;
        OperatorKeyId = operatorKeyId;
        OperatorSecret = operatorSecret;
    }

    public string OperatorKeyId { get; }

    /// <summary>The HMAC secret of the demo operator: must never leave the server.</summary>
    public string OperatorSecret { get; }

    public IServiceProvider Services => _factory.Services;

    /// <summary>
    /// Starts the casino; <paramref name="configureServices"/> runs after the application's own registrations.
    /// <paramref name="settings"/> adds configuration (SPEC-0044: <c>DemoCasino:Lobby:NewGames</c>, …) and
    /// <paramref name="operatorKeyId"/>/<paramref name="operatorSecret"/> replace the generated demo operator key (SPEC-0044:
    /// the key the real Apogeu of the test knows).
    /// </summary>
    public static DemoCasinoHost Start(
        Action<IServiceCollection>? configureServices = null,
        IReadOnlyDictionary<string, string>? settings = null,
        string? operatorKeyId = null,
        string? operatorSecret = null)
    {
        var keyId = operatorKeyId ?? "demo-it-" + Convert.ToHexStringLower(RandomNumberGenerator.GetBytes(8));
        var secret = operatorSecret ?? Convert.ToHexStringLower(RandomNumberGenerator.GetBytes(32));

        var factory = new WebApplicationFactory<Program>().WithWebHostBuilder(host =>
        {
            host.UseSetting("Apogeu:BaseUrl", ApogeuBaseUrl.ToString());
            host.UseSetting("Apogeu:OperatorKeyId", keyId);
            host.UseSetting("Apogeu:OperatorSecret", secret);
            foreach (var (key, value) in settings ?? new Dictionary<string, string>(StringComparer.Ordinal))
            {
                host.UseSetting(key, value);
            }

            if (configureServices is not null)
            {
                host.ConfigureTestServices(configureServices);
            }
        });

        try
        {
            _ = factory.Server;
        }
        catch
        {
            factory.Dispose();
            throw;
        }

        return new DemoCasinoHost(factory, keyId, secret);
    }

    /// <summary>A browser-like client: keeps the cookies the casino sets and sends them back.</summary>
    public HttpClient CreateBrowserClient() =>
        _factory.CreateClient(new WebApplicationFactoryClientOptions
        {
            BaseAddress = CasinoBaseAddress,
            HandleCookies = true,
            AllowAutoRedirect = false,
        });

    /// <summary>A raw client: no cookie handling, so the tests read Set-Cookie and send Cookie themselves.</summary>
    public HttpClient CreateRawClient() =>
        _factory.CreateClient(new WebApplicationFactoryClientOptions
        {
            BaseAddress = CasinoBaseAddress,
            HandleCookies = false,
            AllowAutoRedirect = false,
        });

    public async ValueTask DisposeAsync() => await _factory.DisposeAsync().ConfigureAwait(false);
}
